using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FinishWallVerify {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");string original=SceneManager.GetActiveScene().path;var rows=JArray.Parse(File.ReadAllText(R+"/SourceAssets/B4_Finish/walls_applied.json"));var bad=new List<object>();int triangles=0;foreach(var r in rows){var a=AssetDatabase.LoadAllAssetsAtPath((string)r["oldPath"]).OfType<Mesh>().Single(m=>m.name==(string)r["oldMesh"]);var b=AssetDatabase.LoadAssetAtPath<Mesh>((string)r["newPath"]);bool okay=a.subMeshCount==b.subMeshCount;var av=a.vertices;var bv=b.vertices;var an=a.normals;var bn=b.normals;for(int s=0;s<a.subMeshCount&&okay;s++){var ai=a.GetTriangles(s);var bi=b.GetTriangles(s);okay=ai.Length==bi.Length;for(int i=0;i<ai.Length&&okay;i++)okay=(av[ai[i]]-bv[bi[i]]).sqrMagnitude<1e-12f&&(an[ai[i]]-bn[bi[i]]).sqrMagnitude<1e-12f;triangles+=ai.Length/3;}if(!okay)bad.Add((string)r["name"]);}var baseline=JArray.Parse(File.ReadAllText(R+"/SourceAssets/FloorSurfaceWear/B5_state_after.json"));int missing=0;try{EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_B5_Circular.unity");foreach(var r in baseline){GlobalObjectId.TryParse((string)r["id"],out var gid);var t=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(gid) as Transform;if(!t){missing++;continue;}float[] Arr(JToken j)=>j.ToObject<float[]>();Vector3 V(JToken j){var v=Arr(j);return new Vector3(v[0],v[1],v[2]);}if((t.position-V(r["p"])).sqrMagnitude>1e-8f||(t.localScale-V(r["scale"])).sqrMagnitude>1e-8f||Quaternion.Angle(t.rotation,Quaternion.Euler(V(r["e"])))>.002f||t.gameObject.activeSelf!=(bool)r["active"])bad.Add(new{name=t.name,key="B5 transform"});var cs=t.GetComponents<Collider>();if(cs.Length!=r["colliders"].Count())bad.Add(new{name=t.name,key="B5 collider count"});for(int i=0;i<cs.Length;i++){var c=cs[i];var q=r["colliders"][i];if(c.enabled!=(bool)q["enabled"]||c.isTrigger!=(bool)q["trigger"]||c.GetType().Name!=(string)q["type"]||(c.bounds.center-V(q["center"])).sqrMagnitude>1e-8f||(c.bounds.size-V(q["size"])).sqrMagnitude>1e-8f)bad.Add(new{name=t.name,key="B5 collider"});}var ls=t.GetComponents<Light>();for(int i=0;i<ls.Length;i++){var l=ls[i];var q=r["lights"][i];if(Mathf.Abs(l.intensity-(float)q["intensity"])>.0001f||Mathf.Abs(l.range-(float)q["range"])>.0001f||Mathf.Abs(l.spotAngle-(float)q["spotAngle"])>.0001f||l.enabled!=(bool)q["enabled"]||(new Vector3(l.color.r,l.color.g,l.color.b)-V(q["color"])).sqrMagnitude>1e-8f)bad.Add(new{name=t.name,key="B5 light"});}}}finally{EditorSceneManager.OpenScene(original);}var result=new{wallMeshes=rows.Count,triangles,b5OriginalTransforms=baseline.Count,b5Missing=missing,differences=bad};File.WriteAllText(R+"/Docs/Review/2026-11-09_B4_Finish/wall_verification.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
